// Determine if this is a full sync or specific property check
const input = $input.item.json;

const today = new Date();
const futureDate = new Date();
futureDate.setDate(today.getDate() + 90);

return {
  property_id: input.property_id || null,
  check_in_date: input.check_in_date || null,
  check_out_date: input.check_out_date || null,
  sync_type: input.property_id ? 'specific' : 'full',
  date_range_start: today.toISOString().split('T')[0],
  date_range_end: futureDate.toISOString().split('T')[0],
  is_availability_check: !!input.check_in_date
};

// Detect conflicts in bookings with error handling
try {
  const bookings = $input.all().map(i => i.json).filter(b => b.booking_id);
  const property = $('Loop Properties').item.json;
  const params = $('Prepare Parameters').item.json;

  const conflicts = [];
  const blockedDates = new Set();

  // Build set of all blocked dates
  for (const booking of bookings) {
    if (!booking.check_in_date || !booking.check_out_date) continue;

    const start = new Date(booking.check_in_date);
    const end = new Date(booking.check_out_date);

    for (let d = new Date(start); d < end; d.setDate(d.getDate() + 1)) {
      const dateStr = d.toISOString().split('T')[0];

      if (blockedDates.has(dateStr)) {
        const existing = bookings.find(b => {
          if (!b.check_in_date || !b.check_out_date) return false;
          const bStart = new Date(b.check_in_date);
          const bEnd = new Date(b.check_out_date);
          return d >= bStart && d < bEnd && b.booking_id !== booking.booking_id;
        });

        if (existing) {
          conflicts.push({
            date: dateStr,
            booking1: { id: booking.booking_id, guest: booking.guest_name, platform: booking.external_platform || 'direct' },
            booking2: { id: existing.booking_id, guest: existing.guest_name, platform: existing.external_platform || 'direct' }
          });
        }
      }
      blockedDates.add(dateStr);
    }
  }

  let isAvailable = true;
  let availabilityDetails = null;

  if (params.is_availability_check && params.check_in_date) {
    const reqStart = new Date(params.check_in_date);
    const reqEnd = new Date(params.check_out_date || params.check_in_date);

    for (let d = new Date(reqStart); d < reqEnd; d.setDate(d.getDate() + 1)) {
      if (blockedDates.has(d.toISOString().split('T')[0])) {
        isAvailable = false;
        break;
      }
    }

    availabilityDetails = {
      property_id: property.property_id,
      property_name: property.property_name,
      check_in: params.check_in_date,
      check_out: params.check_out_date,
      available: isAvailable,
      conflicts_found: conflicts.length
    };
  }

  return [{
    json: {
      property_id: property.property_id,
      property_name: property.property_name,
      owner_contact: property.owner_contact,
      preferred_platform: property.preferred_platform,
      total_bookings: bookings.length,
      conflicts: conflicts,
      has_conflicts: conflicts.length > 0,
      availability_check: availabilityDetails,
      sync_timestamp: new Date().toISOString()
    }
  }];
} catch (err) {
  return [{
    json: {
      property_id: null,
      property_name: 'Error',
      total_bookings: 0,
      conflicts: [],
      has_conflicts: false,
      error: err.message,
      sync_timestamp: new Date().toISOString()
    }
  }];
}

// Prepare conflict alert message without AI (fallback)
const data = $json;
const conflicts = data.conflicts || [];

let message = `⚠️ *Calendar Conflict Alert*\n\n`;
message += `🏠 Property: ${data.property_name || 'Unknown'}\n\n`;

if (conflicts.length > 0) {
  message += `🔴 *${conflicts.length} conflict(s) detected:*\n\n`;

  for (const c of conflicts.slice(0, 3)) {
    message += `📅 ${c.date}:\n`;
    message += `  • ${c.booking1?.guest || 'Unknown'} (${c.booking1?.platform || 'direct'})\n`;
    message += `  • ${c.booking2?.guest || 'Unknown'} (${c.booking2?.platform || 'direct'})\n\n`;
  }

  if (conflicts.length > 3) {
    message += `... and ${conflicts.length - 3} more conflicts\n\n`;
  }

  message += `⚡ Please resolve these conflicts immediately!`;
}

return {
  channel: data.preferred_platform || 'telegram',
  recipient: data.owner_contact,
  message: message,
  property_id: data.property_id
};

// Return final result
return {
  success: true,
  processed: true,
  property_id: $json.property_id,
  conflicts_found: $json.has_conflicts || false,
  availability: $json.availability_check
};

// No properties found - return empty result
return {
  success: true,
  processed: false,
  message: 'No properties found to process',
  timestamp: new Date().toISOString()
};
